pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(address(0x1), address(0x2), 100, 100, 0, 0, bytes32(0), false, false);
        vm.deal(address(c), 1 ether);
        bool ok;
        try c.availableForFlashLoan(address(0x2), 0) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        address ft = c.flashFeeToken();
        assertTrue(ft == address(0x1), "flashFeeToken should be 0x1 in reference");
    }
}
